-- Replace the generated 10,000-card Lily library with the supplied, curated
-- collection. Deleting by the reserved prefix also removes delivery-history
-- rows through the existing foreign-key cascade, so no removed card can be
-- selected again for any learner.
DELETE FROM "philology_facts" WHERE "id" LIKE 'lily-library-%';

WITH supplied_facts (ordinal, text) AS (
VALUES
  (1, $$Агата Кристи страдала дисграфией — она почти не могла писать от руки, поэтому надиктовывала все свои великие детективы.$$),
  (2, $$Франц Кафка перед смертью просил своего друга Макса Брода сжечь все его рукописи. Друг ослушался, и мир узнал «Процесс» и «Замок».$$),
  (3, $$Чарльз Диккенс всегда спал головой строго на север. Он верил, что это выравнивает его по магнитным полям Земли и улучшает творчество.$$),
  (4, $$Оноре де Бальзак был кофейным маньяком. Он выпивал до 50 чашек крепкого кофе в день, чтобы поддерживать дикую работоспособность.$$),
  (5, $$Марк Твен обожал кошек больше людей. Когда он работал, вокруг него могло лежать до 19 кошек одновременно.$$),
  (6, $$Лев Толстой имел настолько неразборчивый почерк, что его жена Софья Андреевна переписывала «Войну и мир» от руки вручную семь раз.$$),
  (7, $$Эрнест Хемингуэй предпочитал писать свои романы исключительно стоя, используя высокую конторку.$$),
  (8, $$Виктор Гюго во время работы над «Собором Парижской Богоматери» остриг себе половину волос и бороды, а ножницы выбросил, чтобы не иметь возможности выйти из дома до завершения книги.$$),
  (9, $$Джеймс Джойс писал «Улисса» огромными синими карандашами на больших кусках картона, потому что почти ничего не видел из-за проблем с глазами.$$),
  (10, $$Владимир Набоков писал свои романы («Лолита», «Бледный огонь») на маленьких библиотечных карточках размером 3х5 дюймов, которые потом тасовал.$$),
  (11, $$Артур Конан Дойл искренне ненавидел Шерлока Холмса, считая его «низким жанром», и отвлекающим от его «серьезных» исторических романов.$$),
  (12, $$Льюис Кэрролл (Чарльз Доджсон) был выдающимся математиком и страдал от сильнейшего заикания, но когда общался с детьми, заикание исчезало.$$),
  (13, $$Эдгар Аллан По всю жизнь панически боялся темноты.$$),
  (14, $$Джон Толкин набирал весь текст «Властелина колец» двумя пальцами на старой печатной машинке.$$),
  (15, $$Уильям Шекспир в своем завещании оставил жене только одну вещь: «мою вторую по качеству кровать».$$),
  (16, $$Джордж Orwell (Эрик Блэр) взял свой псевдоним в честь реки Оруэлл в Англии, которую очень любил.$$),
  (17, $$Антон Чехов подписывал свои ранние юмористические рассказы более чем 50 разными псевдонимами (Антоша Чехонте, Брат моего брата, Человек без селезенки).$$),
  (18, $$Стивен Кинг не помнит, как написал свой роман «Томминокеры», так как в тот период находился в глубочайшей алкогольной и наркотической зависимости.$$),
  (19, $$Николай Гоголь обожал рукоделие: он сам вязал шарфы, кроил платья для сестер и подшивал себе жилеты.$$),
  (20, $$Харпер Ли после феноменального успеха «Убить пересмешника» почти полностью отказалась от публичной жизни и не давала интервью десятилетиями.$$),
  (21, $$«Франкенштейн» Мэри Шелли написала в 18 лет на спор с лордом Байроном и своим мужем — кто напишет лучший ужастик.$$),
  (22, $$«Алиса в Стране чудес» изначально называлась «Приключения Алисы под землей».$$),
  (23, $$«451 градус по Фаренгейту» Рэй Брэдбери написал в подвале публичной библиотеки Лос-Анджелеса на арендованной печатной машинке за 9 долларов и 80 центов.$$),
  (24, $$«Гарри Поттер» был отвергнут 12 крупными издательствами, прежде чем маленькое издательство Bloomsbury согласилось его напечатать (и то благодаря дочке директора, которая прочитала первую главу).$$),
  (25, $$«Робинзон Крузо» Даниэля Дефо считается первым классическим английским романом.$$),
  (26, $$«Приключения Тома Сойера» — первая в мире книга, рукопись которой была полностью набрана на печатной машинке.$$),
  (27, $$«Дракула» Брэма Стокера изначально должен был называться просто «Вампир».$$),
  (28, $$«Великий Гэтсби» Фрэнсиса Скотта Фицджеральда при жизни автора продавался плохо и считался коммерческим провалом.$$),
  (29, $$«Хроники Нарнии» Клайва Льюиса были вдохновлены образом фавна, несущего зонтик и подарки через заснеженный лес, который привиделся автору в 16 лет.$$),
  (30, $$«Унесенные ветром» Маргарет Митчелл писала в обратном порядке: она сначала сочинила финальную главу, а затем писала книгу с начала.$$),
  (31, $$«Капитал» Карла Маркса в России впервые был издан легально, так как царская цензура посчитала его «слишком скучным математическим трудом», который никто не станет читать.$$),
  (32, $$«Три мушкетера» Александра Дюма писались для публикации в газете по строчкам. Дюма платили за каждую строчку, поэтому он придумал слугу Гримо, который отвечал только «да» или «нет», увеличивая объем текста.$$),
  (33, $$«Книга рекордов Гиннесса» изначально задумывалась как авторитетный справочник для разрешения споров и драк в пивных пабах.$$),
  (34, $$«Властелин колец» писался Толкином 12 лет и задумывался как одна огромная книга, но издатели разделили ее на три части из-за дефицита бумаги после войны.$$),
  (35, $$«50 оттенков серого» изначально создавались как фанфик по сумеречной саге Стефани Майер и публиковались на фанатских форумах.$$),
  (36, $$«Скотный двор» Оруэлла долго не хотели издавать в Англии и США, боясь испортить отношения с СССР во время Второй мировой войны.$$),
  (37, $$«Мастер и Маргарита» Булгакова в первой редакции вообще не содержала Мастера и Маргариту — это была книга о дьяволе. Автор сжег ее и написал заново.$$),
  (38, $$«Код да Винчи» Дэна Брауна запрещен в Ватикане, что сделало книге колоссальную рекламу.$$),
  (39, $$«Вини-Пух» Алана Милна списан с реальных игрушек его сына Кристофера Робина, которые сейчас хранятся в Нью-Йоркской публичной библиотеке.$$),
  (40, $$«Зеленые яйца и ветчина» доктора Сьюза написана всего с использованием 50 различных слов — автор выиграл спор у своего издателя.$$),
  (41, $$Самая продаваемая книга всех времен (после Библии и Цитатника Мао) — «Дон Кихот» Мигеля де Сервантеса (около 500 млн копий).$$),
  (42, $$Самый длинный роман в мире — «В поисках утраченного времени» Марселя Пруста. В нем более 9,6 миллиона знаков (с пробелами).$$),
  (43, $$Самая переводимая художественная книга в мире — «Маленький принц» Антуана де Сент-Экзюпери (переведена на более чем 300 языков и диалектов).$$),
  (44, $$Самый богатый писатель в мире — Джоан Роулинг. Ее состояние превышает 1 миллиард долларов.$$),
  (45, $$Самый плодовитый писатель — испанец Корн Тельядо. За свою жизнь он написал около 4000 любовных романов.$$),
  (46, $$Самый большой печатный словарь — Оксфордский английский словарь. Он содержит более 600 тысяч слов.$$),
  (47, $$Самый продаваемый поэт в истории — Уильям Шекспир.$$),
  (48, $$Самая дорогая книга в мире — «Лестерский кодекс» Леонардо да Винчи. Билл Гейтс купил ее на аукционе за 30,8 млн долларов.$$),
  (49, $$Самая маленькая книга в мире имеет размер 0,74 на 0,75 мм. Прочесть ее можно только под электронным микроскопом.$$),
  (50, $$Самый длинный заголовок книги состоит из более чем 26 000 знаков и занесен в Книгу Гиннесса.$$),
  (51, $$Слово «робот» придумал не ученый, а чешский писатель Карел Чапек в своей фантастической пьесе «R.U.R.» в 1920 году.$$),
  (52, $$Синдром Стендаля — реальное психическое расстройство, когда человек падает в обморок от избытка эмоций при виде произведений искусства. Назван в честь писателя, который описал это состояние.$$),
  (53, $$Слово «утопия» придумал Томас Мор в 1516 году. С греческого оно переводится буквально как «место, которого нет».$$),
  (54, $$Термин «киберпространство» впервые ввел фантаст Уильям Гибсон в своем романе «Нейромант» (1984).$$),
  (55, $$Шерлок Холмс популяризировал лупу и отпечатки пальцев в криминалистике до того, как Скотленд-Ярд начал массово использовать их в реальности.$$),
  (56, $$Слово «неологизм» само когда-то было неологизмом.$$),
  (57, $$Роман «Тщетность» Моргана Робертсона описал гибель огромного корабля «Титан» от столкновения с айсбергом за 14 лет до реальной катастрофы «Титаника».$$),
  (58, $$Слово «бред» (в значении чепухи) пошло от фамилии французского врача Бреди, который писал скучные статьи.$$),
  (59, $$«Алиса в стране чудес» дала название неврологическому синдрому (микропсия), при котором человеку кажется, что его тело или окружающие предметы резко уменьшаются или увеличиваются.$$),
  (60, $$Язык эльфов (квенья и синдарин) Толкин создал до того, как написал книги. Он придумал мир Средиземья только для того, чтобы этим языкам было где существовать.$$),
  (61, $$Данте Алигьери никогда не видел свою музу Беатриче ближе, чем на расстоянии вытянутой руки, и разговаривал с ней всего дважды в жизни.$$),
  (62, $$Иоганн Гёте панически боялся высоты и лаял на собак, чтобы прогнать их.$$),
  (63, $$Оскар Уайльд ходил по улицам Лондона с подсолнухом или лилией в руках, пропагандируя эстетизм.$$),
  (64, $$Джордж Байрон держал в своей комнате в Кембридже живого медведя, так как правила университета запрещали держать собак.$$),
  (65, $$Александр Пушкин участвовал более чем в 20 дуэлях. Почти все они заканчивались примирением благодаря его друзьям.$$),
  (66, $$Вольтер спал всего по 4 часа в сутки и обладал феноменальной памятью — мог цитировать огромные тексты, прочитав их один раз.$$),
  (67, $$Жюль Верн никогда не путешествовал так много, как его герои, и большую часть описаний природы брал из географических журналов.$$),
  (68, $$Джек Лондон стал миллионером благодаря своему писательскому труду, но умер в бедности из-за долгов и трат на безумные проекты.$$),
  (69, $$Роберт Льюис Стивенсон придумал «Остров сокровищ», когда рисовал карту для своего пасынка, чтобы развлечь его в дождливый день.$$),
  (70, $$Федор Достоевский написал роман «Игрок» всего за 26 дней, так как ему нужно было срочно выплатить огромные карточные долги издателю.$$),
  (71, $$Запах старых книг обусловлен химическим распадом соединений в бумаге (в основном лигнина). Этот процесс выделяет легкий ванильный аромат.$$),
  (72, $$В библиотеках Гарварда хранятся книги, переплетенные в настоящую человеческую кожу (антроподермический переплет).$$),
  (73, $$Самая старая непрерывно действующая библиотека в мире находится в монастыре Святой Екатерины на Синае (Египет), она работает с VI века.$$),
  (74, $$Термин «библиоосмия» означает непреодолимое желание нюхать книги.$$),
  (75, $$В древней Александрийской библиотеке все прибывающие в город корабли обыскивали, изымали любые свитки и книги, копировали их, оригинал отдавали в библиотеку, а копию возвращали владельцам.$$),
  (76, $$Книжные черви — это не метафора, а реальные личинки жуков-точильщиков, которые прогрызают страницы старых книг.$$),
  (77, $$В Норвегии государство покупает 1000 экземпляров каждой изданной норвежской книги и распределяет их по всем библиотекам страны для поддержки авторов.$$),
  (78, $$Первая печатная книга в мире — Алмазная сутра (буддийский текст), отпечатанная в Китае в 868 году нашей эры с помощью деревянных клише.$$),
  (79, $$Самая большая библиотека в мире — Библиотека Конгресса США (хранит более 170 миллионов единиц хранения).$$),
  (80, $$В средние века книги в библиотеках приковывали к полкам железными цепями, чтобы их не украли, так как они стоили целое состояние.$$),
  (81, $$Стивен Кинг публикует свои книги под псевдонимом Ричард Бахман, чтобы проверить, купят ли его книги без известного имени (их покупали хуже).$$),
  (82, $$Джордж Мартин («Песнь Льда и Пламени») до сих пор пишет свои книги на старом компьютере без интернета в операционной системе DOS на текстовом редакторе WordStar 4.0.$$),
  (83, $$Дэн Браун перед тем как стать писателем, пытался построить карьеру поп-певца и автора песен.$$),
  (84, $$Анджей Сапковский продал права на игру «Ведьмак» студии CD Projekt RED за фиксированную небольшую сумму (около 9500 долларов), не поверив в успех видеоигры, о чем потом сильно жалел.$$),
  (85, $$Пауло Коэльо написал «Алхимика» всего за две недели. Он утверждает, что книга «уже была написана в его душе».$$),
  (86, $$Сумеречная сага приснилась Стефани Майер во сне: ей привиделся луг и парень-вампир, который светился на солнце.$$),
  (87, $$Нил Гейман написал «Коралину» как сказку на ночь для своих дочерей.$$),
  (88, $$Терри Пратчетт перед смертью распорядился, чтобы жесткий диск его компьютера со всеми незавершенными романами был раздавлен паровым катком. Его волю исполнили.$$),
  (89, $$Сьюзен Коллинз придумала «Голодные игры», когда переключала каналы телевизора: на одном показывали реалити-шоу, а на другом — репортаж о войне в Ираке.$$),
  (90, $$Джаспер Фффорде получил 76 отказов от издательств, прежде чем опубликовал свой первый бестселлер «Дело Дженни, или Эйра немилосердия».$$),
  (91, $$Фраза «Остаться у разбитого корыта» вошла в язык благодаря «Сказке о рыбаке и рыбке» Пушкина.$$),
  (92, $$Выражение «Большой Брат следит за тобой» из романа Оруэлла «1984» стало главным символом тоталитарного контроля.$$),
  (93, $$«Быть или не быть» Шекспира — самый цитируемый и переводимый монолог в истории мирового театра.$$),
  (94, $$Фраза «Красота спасет мир» Достоевского («Идиот») в оригинале имела глубокий религиозный контекст, а не эстетический.$$),
  (95, $$«В начале было Слово» — самая комментируемая первая строчка в истории литературы (Евангелие от Иоанна).$$),
  (96, $$Понятие «Бальзаковский возраст» изначально означало женщину всего лишь от 30 до 40 лет.$$),
  (97, $$Выражение «Счастливые часов не наблюдают» принадлежит Александру Грибоедову («Горе от ума»).$$),
  (98, $$Фраза «Рукописи не горят» Булгакова стала гимном стойкости искусства перед лицом цензуры.$$),
  (99, $$Слово «Лилипут» было полностью выдумано Джонатаном Свифтом для «Путешествий Гулливера».$$),
  (100, $$Фраза «Элементарно, Ватсон!» ни разу не встречалась в оригинальных книгах Артура Конан Дойла — ее придумали в первых театральных постановках и киноадаптациях.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  CASE WHEN ordinal BETWEEN 51 AND 60 THEN 'PHILOLOGY' ELSE 'LITERATURE' END,
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;
